const M=Model,$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('sv-SE',{maximumFractionDigits:2}).format(n)+' kr',label=m=>new Intl.DateTimeFormat('sv-SE',{month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(m+'-01'));
const key='kraftringen.provisionsstudio.v1';let state,loadError='';try{state=JSON.parse(localStorage.getItem(key))||M.initial()}catch{state=M.initial();loadError='Sparade data kunde inte läsas. En tillfällig demo visas; tidigare data har inte skrivits över.'}let partner='e1',view='partners',start='2026-01',end='2026-12',compareA='',compareB='';
const tabs=[['partners','◈','Partner & modell','Välj partner och utforska hur ersättningen fungerar.'],['versions','▤','Modellversioner','Planera nya nivåer med tydliga giltighetsperioder.'],['simulation','◷','Simulering','Följ förskott, mognad och ersättning månad för månad.'],['comparison','⇄','Jämför versioner','Jämför två modeller på exakt samma demoavtal.'],['report','▥','Provisionsrapport','Se partnerns vy och hämta månadsvisa Excel-underlag.'],['tests','✓','Beslut & tester','Se vad som är verifierat, föreslaget och fortfarande öppet.']];
const p=()=>M.partners.find(x=>x.id===partner),vs=()=>state.versions[partner],data=()=>M.orders.filter(o=>o.partner===partner),period=()=>M.months.filter(m=>m>=start&&m<=end),sum=rows=>rows.reduce((s,r)=>s+r.amount,0),basis=v=>v.basis==='active'?'Aktiverat avtal':'Bindande avtal',kind=v=>v.kind==='maturity'?'Avtalsmognad med förskott':'Rak ersättning',selected=(a,b)=>a===b?' selected':'';
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',5000)}
function save(mutator,msg){if(!window.StudioAccess?.allowed())return false;if(loadError){toast('Återställ demodata uttryckligen innan du sparar.');return false}try{const current=JSON.parse(localStorage.getItem(key));if(current&&current.revision!==state.revision)throw Error('Data har ändrats i en annan flik. Ladda om innan du sparar.');const next=structuredClone(state);mutator(next);next.revision++;localStorage.setItem(key,JSON.stringify(next));state=next;toast(msg);return true}catch(e){toast('Kunde inte spara: '+e.message);return false}}
function audit(s,text){s.audit.unshift({at:new Date().toISOString(),partner:p().name,text});s.audit=s.audit.slice(0,100)}
const calc=(m,models=vs())=>M.calculate(data(),models,m);
function report(m){const snapshot=state.snapshots[partner+'|'+m];return snapshot?{...snapshot.report,locked:true,snapshot}: {...calc(m),locked:false};}
function stats(rows){return `<div class="grid"><article class="card dark"><small>SIMULERAD ERSÄTTNING · VALD PERIOD</small><div class="metric">${money(sum(rows))}</div><small>Fiktivt utfall enligt valda modellversioner</small></article><article class="card"><small>NYA KVALIFICERANDE AVTAL</small><div class="metric">${rows.reduce((s,r)=>s+r.qualified,0)}</div><small>${esc(basis(vs()[0]))} under perioden</small></article><article class="card"><small>HISTORIK SOM BEVARAS</small><div class="metric">${period().filter(m=>state.snapshots[partner+'|'+m]).length} månader</div><small>Låsta demounderlag med egna parametrar</small></article></div>`}
function chart(a,b){const max=Math.max(...a.map(r=>r.amount),...b.map(r=>r.amount),1);return `<div class="key"><span>Jämförelsemodell</span><span>Versionsstyrt förslag</span></div><div class="chart" role="img" aria-label="Månadsvis jämförelse, exakta belopp finns i tabellen nedanför">${a.map((r,i)=>`<div class="barcol"><div class="barpair"><i style="height:${r.amount/max*100}%" title="${money(r.amount)}"></i><i style="height:${b[i].amount/max*100}%" title="${money(b[i].amount)}"></i></div><span>${label(r.month).split(' ')[0]}</span></div>`).join('')}</div>`}
function table(rows,actions=false){return `<div class="tablewrap"><table><thead><tr><th>Månad</th><th class="num">Godkända</th><th class="num">Kvalificerade</th><th class="num">Förskott</th><th class="num">${actions?'Övrig ersättning':vs()[0].kind==='maturity'?'Utöver förskott':'Rak ersättning'}</th><th class="num">Totalt</th>${actions?'<th>Status / underlag</th>':'<th>Beräkning</th>'}</tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${label(r.month)}</strong></td><td class="num">${r.approved}</td><td class="num">${r.qualified}</td><td class="num">${money(r.advance)}</td><td class="num">${money(r.extra)}</td><td class="num"><strong>${money(r.amount)}</strong></td><td>${actions?`<span class="pill ${r.locked?'green':'amber'}">${r.locked?'Låst demo':'Preliminärt'}</span> <button data-export="${r.month}">Fakturaunderlag (Excel) ↓</button> ${r.locked?'':`<button data-lock="${r.month}">Lås månad</button>`}`:`<button data-detail="${r.month}">Visa detaljer ↗</button>`}</td></tr>`).join('')}<tr><td><strong>Summa</strong></td><td colspan="4"></td><td class="num"><strong>${money(sum(rows))}</strong></td><td></td></tr></tbody></table></div>`}
function partnersView(){const a=p(),v=vs()[0],rows=period().map(m=>calc(m));return stats(rows)+`<div class="grid two spacer"><article class="card"><div class="row"><h2>${esc(a.name)}</h2><span class="pill">Fiktiv partner</span></div><p class="muted">${a.type} · ${data().length} demoavtal · januari–december 2026</p><div class="flow"><div><b>01 · Godkänt</b>Daterad godkännandehändelse</div><div><b>02 · Bindande</b>Ångerperiod passerad i demo</div><div><b>03 · Aktiverat</b>Leveransen påbörjad i demo</div></div><div class="listline"><div class="row"><b>${kind(v)}</b><span class="pill amber">Föreslagen modellserie</span></div><p>${v.kind==='maturity'?`${v.advance} % förskott vid godkännande. Avräkning mot samma godkännandemånad och modellversion.`:`Fast belopp när avtalet blir ${v.basis==='active'?'aktiverat':'bindande'}. Varje avtals-ID räknas en gång.`}</p></div><div class="listline"><b>${money(v.rate)} → ${money(vs().at(-1).rate)}</b><p>Modellserien väljer nivå efter ${v.kind==='maturity'?'godkännandedatum':'kvalificeringsdatum'}. Historiskt låsta rapporter använder sin sparade ögonblicksbild.</p></div><div class="actions spacer"><button class="primary" data-go="versions">Hantera modellversioner →</button><button data-newmodel>Skapa ny modell</button></div></article><article class="card"><h2>Vad vet vi – och vad provar vi?</h2><div class="listline"><span class="pill green">Verifierat i befintlig kod</span><p>${a.type==='Face2face'?'1 500 kr per bindande avtal. 80 % garanterat förskott. Avräkning per godkännandemånad. Förskott återkrävs inte.':a.type==='Fastighetspartner'?'Rak ersättning per aktivering. Ett lokalt belopp används för samtliga valda månader. Befintligt underlag är månadsaggregat utan avtals-ID.':'Modellversioner är beskrivande förslag. Ingen verifierad automatisk modell för Företagsrådgivare är ansluten.'}</p></div><div class="listline"><span class="pill amber">Föreslagen funktion</span><p>Versionsperioder, nya kvalificeringsgrunder, historiska låsningar och månadsrapporter för alla partnertyper.</p></div><div class="listline"><span class="pill peach">Fiktiva demoantaganden</span><p>Partnernamn, alla orderhändelser, juliökning på 20 %, nya ersättningsnivåer och låsningar januari–juni. December är ett scenario, inte observerat utfall.</p></div></article></div><article class="card spacer"><div class="row"><h2>En ny nivå. Samma historik.</h2><button data-go="report">Visa partnerns rapport →</button></div><div class="timeline">${M.months.map((m,i)=>`<div class="${i>5?'future':''}">${label(m).split(' ')[0]}<i></i><small>${i<6?'Låst':'Förslag'}</small></div>`).join('')}</div><p class="muted">Januari–juni är sparade demounderlag. Från juli kan nya nivåer simuleras. Redan låsta underlag räknas aldrig om när ett modellförslag ändras.</p></article>`}
function versionsView(){return `<article class="card"><div class="row sectiontitle"><div><h2>Versionskedja för ${esc(p().name)}</h2><small>Sammanhängande datumintervall · inklusive från- och tilldatum</small></div><div class="actions"><button data-newmodel>Ny modell</button><button class="primary" data-addversion>+ Ny version</button></div></div>${vs().map((v,i)=>`<div class="version"><div class="stamp">V${i+1}</div><div class="body"><div class="row"><h3>${esc(v.name)}</h3><span class="pill ${v.status==='Förslag'?'amber':'green'}">${esc(v.status)}</span></div><p>${v.from} — ${v.to} · ${kind(v)} · ${basis(v)}</p><div class="actions"><b>${money(v.rate)} / avtal</b><span>Förskott ${v.kind==='flat'?0:v.advance} %</span><button data-edit="${i}">Redigera förslag</button></div></div></div>`).join('')}</article><div class="notice warn"><b>Granskad i demo betyder inte aktiverad.</b> Alla statusar beskriver förslag i denna app. Förskottsmodeller väljs vid godkännandet och följer avtalet vid senare avräkning. Raka modeller väljs vid bindande eller aktivering enligt vald grund.</div><article class="card"><h2>Så bevaras tidigare underlag</h2><div class="flow"><div><b>1. Planera</b>Lägg ny nivå från ett datum. Föregående period avslutas dagen innan.</div><div><b>2. Simulera</b>Jämför utfall för samma demoordrar och kontrollera datumen.</div><div><b>3. Lås i demo</b>Spara månadsbelopp, avtals-ID:n, regler och modellversion tillsammans.</div><div><b>4. Hämta historik</b>Excel för en låst månad hämtas från samma ögonblicksbild.</div></div><p class="muted spacer">Byte av modelltyp eller kvalificeringsgrund görs med ”Ny modell”, som ersätter hela förslagsserien. Det påverkar inte låsta underlag. Blandade grunder inom en serie tillåts inte.</p></article>`}
function simulationView(){const proposed=period().map(m=>calc(m)),base=period().map(m=>calc(m,[{...M.baseline(p()),rate:state.localRates[partner]}]));return stats(proposed)+`<article class="card spacer"><div class="row sectiontitle"><div><h2>${p().type==='Fastighetspartner'?'Samma belopp hela perioden – eller nivå per datum?':'Utfall genom året'}</h2><small>Teoretisk simulering. Historiska låsningar används först i provisionsrapporten.</small></div><button data-go="versions">Ändra parametrar</button></div><label style="max-width:300px">Jämförelse: lokalt belopp för hela perioden, kr<input id="localrate" type="number" min="0" max="1000000" step="0.01" value="${state.localRates[partner]}"></label><small class="spacer">Jämförelsen använder ${basis(M.baseline(p())).toLowerCase()} och grundmodellens ${M.baseline(p()).advance} % förskott. Förslaget använder den valda versionsserien.</small>${chart(base,proposed)}<div class="row spacer"><span>En nivå: <b>${money(sum(base))}</b></span><span>Versionsstyrt: <b>${money(sum(proposed))}</b></span><span class="pill peach">Skillnad ${money(sum(proposed)-sum(base))}</span></div></article><article class="card"><h2>Simulering per månad</h2>${table(proposed)}<details><summary>Visa exakt jämförelse per månad</summary><div class="tablewrap"><table><thead><tr><th>Månad</th><th>En nivå hela perioden</th><th>Versionsstyrt</th><th>Skillnad</th></tr></thead><tbody>${base.map((r,i)=>`<tr><td>${label(r.month)}</td><td>${money(r.amount)}</td><td>${money(proposed[i].amount)}</td><td>${money(proposed[i].amount-r.amount)}</td></tr>`).join('')}</tbody></table></div></details></article>`}
function comparisonView(){const versions=vs();if(!versions.some(v=>v.id===compareA))compareA=versions[0].id;if(!versions.some(v=>v.id===compareB))compareB=versions.at(-1).id;const a=versions.find(v=>v.id===compareA),b=versions.find(v=>v.id===compareB),ar=period().map(m=>calc(m,[{...a,from:'2026-01-01',to:'2026-12-31'}])),br=period().map(m=>calc(m,[{...b,from:'2026-01-01',to:'2026-12-31'}]));return `<article class="card"><div class="formgrid"><label>Version A<select id="compareA">${versions.map(v=>`<option value="${v.id}"${selected(v.id,compareA)}>${esc(v.name)}</option>`).join('')}</select></label><label>Version B<select id="compareB">${versions.map(v=>`<option value="${v.id}"${selected(v.id,compareB)}>${esc(v.name)}</option>`).join('')}</select></label></div><div class="notice">Båda versionerna tillämpas hypotetiskt över hela demoåret för en rättvis parameterjämförelse. Giltighetsdatum och historiska låsningar används inte här. Versionsbytet i kalendern visas under Simulering.</div><div class="grid"><div><small>VERSION A · ${esc(a.name)}</small><div class="metric">${money(sum(ar))}</div><small>${money(a.rate)}, ${a.advance} % förskott, ${basis(a)}</small></div><div><small>VERSION B · ${esc(b.name)}</small><div class="metric">${money(sum(br))}</div><small>${money(b.rate)}, ${b.advance} % förskott, ${basis(b)}</small></div><div><small>SKILLNAD B − A</small><div class="metric">${money(sum(br)-sum(ar))}</div><small>${sum(ar)?((sum(br)/sum(ar)-1)*100).toFixed(1)+' %':'Procent saknar basvärde'}</small></div></div></article><article class="card"><h2>Samma avtal, två regeluppsättningar</h2><div class="tablewrap"><table><thead><tr><th>Månad</th><th class="num">Version A</th><th class="num">Version B</th><th class="num">Skillnad</th></tr></thead><tbody>${ar.map((r,i)=>`<tr><td>${label(r.month)}</td><td class="num">${money(r.amount)}</td><td class="num">${money(br[i].amount)}</td><td class="num"><b>${money(br[i].amount-r.amount)}</b></td></tr>`).join('')}</tbody></table></div></article>`}
function reportView(){const rows=period().map(report);return `<article class="card"><div class="reportbrand row"><div><p class="eyebrow">FÖRHANDSGRANSKNING · PARTNERNS VY</p><h2>${esc(p().name)}</h2><small>Din provisionsöversikt · ${label(start)} – ${label(end)}</small></div><button class="primary" id="exportsummary">Sammanfattning (Excel) ↓</button></div><div class="grid"><div><small>ERSÄTTNING I URVALET</small><div class="metric">${money(sum(rows))}</div><small>Exkl. moms · inte utbetalt belopp</small></div><div><small>LÅST HISTORIK</small><div class="metric">${rows.filter(r=>r.locked).length} månader</div><small>Sparad ögonblicksbild i denna webbläsare</small></div><div><small>PRELIMINÄRT FÖRSLAG</small><div class="metric">${rows.filter(r=>!r.locked).length} månader</div><small>Beräknas från aktuell förslagsserie</small></div></div><div class="notice warn">DEMO – ej faktura. Januari–juni är förlåsta demoexempel. Övriga månader är preliminära tills du väljer ”Lås månad”. Inga betalningar eller verkliga fakturor skapas.</div>${table(rows,true)}<small class="spacer">Excel innehåller fakturaunderlag, månadsöversikt, avräkning, orderunderlag och modellparametrar. Nedladdningen använder samma belopp som denna rapport. Spara-dialogens utseende beror på webbläsaren.</small><div id="downloadlink" role="status"></div></article><article class="card"><h2>Kontrollera låst historik</h2><p class="muted">Ändra en tidigare modells ersättningsnivå i Modellversioner. Simulatorn visar den hypotetiska ändringen, men låsta månadsrader och deras Excel-belopp ligger kvar. Denna låsning är lokal demofunktion, inte ett manipulationsskyddat ekonomiskt arkiv.</p><button data-go="versions">Prova att ändra ett modellförslag →</button></article>`}
function runTests(){const out=[];function test(name,fn){try{fn();out.push({name,ok:true})}catch(e){out.push({name,ok:false,error:e.message})}}const eq=(a,b)=>{if(Math.abs(a-b)>.001)throw Error(`${a} ≠ ${b}`)},flat={id:'a',name:'test',from:'2026-01-01',to:'2026-12-31',kind:'flat',rate:300,advance:0,basis:'binding'},o=(id,d)=>({id,approved:d,binding:d,active:d});
test('Övergång 30 juni / 1 juli: rätt nivå på rätt datum',()=>{const rows=[o('1','2026-06-30'),o('2','2026-07-01')],v=[{...flat,to:'2026-06-30'},{...flat,id:'b',from:'2026-07-01',rate:400}];eq(M.calculate(rows,v,'2026-06').amount,300);eq(M.calculate(rows,v,'2026-07').amount,400)});
test('Historisk låsning: ändrad nivå påverkar inte sparat underlag',()=>{const s=M.snapshot(M.partners[0],[flat],'2026-06',[o('1','2026-06-03')]);const before=JSON.stringify(s);flat.rate=900;eq(s.report.amount,300);if(before!==JSON.stringify(s))throw Error('Snapshot ändrad');flat.rate=300});
test('Månadsvis avräkning: förskott betalas bara första månaden',()=>{const v={...flat,kind:'maturity',rate:100,advance:80};const rows=Array.from({length:10},(_,i)=>({id:''+i,approved:'2026-01-05',binding:i<5?'2026-01-20':'2026-02-20',active:''}));eq(M.calculate(rows,[v],'2026-01').amount,800);eq(M.calculate(rows,[v],'2026-02').amount,200);eq(M.calculate(rows,[v],'2026-03').amount,0)});
test('Dubblettskydd: samma avtals-ID räknas endast en gång',()=>{const a=o('1','2026-01-01');eq(M.calculate([a,a],[flat],'2026-01').amount,300)});
test('Motstridiga dubbletter stoppas',()=>{let stopped=false;try{M.calculate([o('1','2026-01-01'),o('1','2026-02-01')],[flat],'2026-01')}catch{stopped=true}if(!stopped)throw Error('Tillåten konflikt')});
test('Mognad: juniavtal behåller juni-nivå vid bindande i juli',()=>{const v=[{...flat,kind:'maturity',rate:100,advance:80,to:'2026-06-30'},{...flat,id:'b',kind:'maturity',rate:200,advance:80,from:'2026-07-01'}];const rows=[{id:'1',approved:'2026-06-10',binding:'2026-07-10',active:''}];eq(M.calculate(rows,v,'2026-06').amount,80);eq(M.calculate(rows,v,'2026-07').amount,20)});
test('Periodval: januari–mars innehåller exakt tre månader',()=>eq(M.months.filter(m=>m>='2026-01'&&m<='2026-03').length,3));
test('Överlappande versionsperioder stoppas',()=>{let stopped=false;try{M.validate([flat,{...flat,id:'b',from:'2026-07-01'}])}catch{stopped=true}if(!stopped)throw Error('Överlapp tillåtet')});
test('Lucka mellan versioner stoppas',()=>{let stopped=false;try{M.validate([{...flat,to:'2026-06-30'},{...flat,id:'b',from:'2026-07-02'}])}catch{stopped=true}if(!stopped)throw Error('Lucka tillåten')});
test('Aktiveringsgrund: bindande i juni ger ersättning först i juli',()=>{const rows=[{id:'1',approved:'2026-05-01',binding:'2026-06-01',active:'2026-07-01'}];eq(M.calculate(rows,[{...flat,basis:'active'}],'2026-06').amount,0);eq(M.calculate(rows,[{...flat,basis:'active'}],'2026-07').amount,300)});
test('Saknat godkännandedatum stoppar beräkning',()=>{let stopped=false;try{M.calculate([{id:'1',approved:'',binding:'2026-01-01'}],[flat],'2026-01')}catch{stopped=true}if(!stopped)throw Error('Datum saknas men godkändes')});
test('Årsavräkning: ett rakt avtal ger ersättning en enda månad',()=>{eq(M.months.reduce((s,m)=>s+M.calculate([o('1','2026-03-01')],[flat],m).amount,0),300)});return out}
window.runTests=runTests;
function testsView(){const results=runTests();return `<div class="grid"><article class="card dark"><small>AUTOMATISKA LOGIKTESTER · KÖRS NU</small><div class="metric">${results.filter(t=>t.ok).length} / ${results.length}</div><small>Isolerade fiktiva testdata, inga produktionsanrop</small></article><article class="card"><small>KÄLLGRANSKNING</small><div class="metric">3 moduler</div><small>Face2face, Fastighetspartner, modellförslag</small></article><article class="card"><small>PRODUKTIONSKOPPLINGAR</small><div class="metric">0</div><small>Ingen CRM-, GitHub- eller ekonomiintegration</small></article></div><article class="card spacer"><div class="row"><h2>Testprotokoll</h2><button id="runtests">Kör tester igen</button></div>${results.map(t=>`<div class="listline row"><span>${esc(t.name)}</span><span class="pill ${t.ok?'green':'peach'}">${t.ok?'✓ Godkänt':esc(t.error)}</span></div>`).join('')}</article><div class="grid two"><article class="card"><h2>Öppna beslut</h2>${[['Beslutat: valbara kvalificeringsvillkor','Aktiverat avtal är grundvillkoret för Fastighetspartner. Nya modeller kan använda andra kvalificeringsvillkor, exempelvis bindande avtal. Bekräftat av beställaren 26 november 2026.'],['Nivåer för företagsrådgivare','Rak modell och belopp är demoantaganden. Verifierad automatisk modell saknas i källan.'],['Vilket datum låser modellversionen?','Förslag: godkännandedatum vid förskott; kvalificeringsdatum vid rak modell.'],['Rättningar efter låsning','Förslag: separat justering i ny period. Kredit/rättelse och attestflöde är inte implementerade.'],['Fakturering och attest','Vem får låsa, godkänna och fakturera? Behöver beslutas före verklig drift.']].map(([a,b])=>`<div class="listline"><h3>${a}</h3><p>${b}</p><span class="pill ${a.startsWith('Beslutat')?'green':'amber'}">${a.startsWith('Beslutat')?'Bekräftad inriktning':'Öppet beslut'}</span></div>`).join('')}</article><article class="card"><h2>Kända begränsningar & källor</h2><p class="muted">Befintlig Sites-källa granskad 26 november 2026, version 42, källrevision <code>8a4bf2680cbf</code>.</p><ul><li><code>partner-commission.js</code>: Face2face 1 500 kr, 80 % förskott per godkännandemånad.</li><li><code>property-commission.js</code>: aktiveringar × lokalt belopp; samma nivå hela urvalet.</li><li><code>internal-sales.js</code>: modellversioner är enbart beskrivningar.</li></ul><p class="muted">Alla avtals-ID:n i denna app är nytillverkad demodata. Fastighetsprototypens aggregat kan inte i sig bevisa att ett verkligt avtal bara räknas en gång.</p><p class="muted">Lokal lagring utan gemensam server, verklig rollstyrning eller revisionssäkert arkiv. Rensad webbläsardata tar bort förslag och låsningar. Inga negativa återkrav, momsberäkningar, betalningar eller kreditfakturor ingår. Retroaktiva modellbyten är simuleringar; automatisk justeringsavräkning mot tidigare låsta utbetalningsunderlag är inte implementerad. Använd ett framtida versionsdatum för planerade nivåändringar.</p><p class="muted">Windows Spara-dialog och Excel på en fysisk Windowsdator är inte verifierade. Årets senare månader är fiktiva scenarier.</p><span class="pill green">Verifierat i denna demo: beräkningslogik</span></article></div><article class="card spacer"><h2>Lokal ändringslogg</h2>${state.audit.length?state.audit.map(a=>`<div class="listline"><small>${esc(a.at)} · ${esc(a.partner)}</small>${esc(a.text)}</div>`).join(''):'<p class="muted">Inga egna ändringar ännu. De förifyllda låsningarna är demoantaganden.</p>'}</article>`}
function render(){if(!window.StudioAccess?.allowed())return;const t=tabs.find(t=>t[0]===view);$('#title').textContent=t[2];$('#subtitle').textContent=t[3];$('#type').textContent=p().type;$('#nav').innerHTML=tabs.map(t=>`<button data-go="${t[0]}" class="${view===t[0]?'active':''}" ${view===t[0]?'aria-current="page"':''}><b>${t[1]}</b>${t[2]}</button>`).join('');try{$('#content').innerHTML=(loadError?`<div class="error">${loadError}</div>`:'')+({partners:partnersView,versions:versionsView,simulation:simulationView,comparison:comparisonView,report:reportView,tests:testsView}[view]())}catch(e){$('#content').innerHTML=`<div class="error">${esc(e.message)}</div><button data-go="versions">Kontrollera modellversioner</button>`}bind()}
function showDialog(html){$('#dialog').innerHTML=`<button class="close" aria-label="Stäng dialog">×</button>${html}`;$('#dialog .close').onclick=()=>$('#dialog').close();$('#dialog').showModal()}
function editModel(mode,index){const old=vs()[index||0],v=mode==='add'?{...vs().at(-1),name:'Ny ersättningsnivå',from:'2026-10-01',to:'2026-12-31',status:'Förslag'}:mode==='new'?{...old,name:'Ny modell',from:'2026-01-01',to:'2026-12-31',status:'Förslag'}:old;showDialog(`<h2>${mode==='new'?'Skapa ny modellserie':mode==='add'?'Ny modellversion':'Redigera modellförslag'}</h2><p>${mode==='new'?'Ersätter den föreslagna modellserien för hela demoåret. Låsta underlag bevaras.':'Ändringen gäller endast simulering och ännu olåsta demounderlag.'}</p><form id="modelform"><div class="formgrid"><label class="full">Namn<input name="name" maxlength="80" value="${esc(v.name)}" required></label><label>Modelltyp<select name="kind" ${mode==='new'?'':'disabled'}><option value="flat"${selected(v.kind,'flat')}>Rak ersättning</option><option value="maturity"${selected(v.kind,'maturity')}>Avtalsmognad med förskott</option></select></label><label>Kvalificeringsgrund<select name="basis" ${mode==='new'?'':'disabled'}><option value="binding"${selected(v.basis,'binding')}>Bindande avtal</option><option value="active"${selected(v.basis,'active')}>Aktiverat avtal</option></select></label><label>Provision, kr per avtal<input name="rate" type="number" min="0" max="1000000" step="0.01" value="${v.rate}" required></label><label>Förskott, % av provision<input name="advance" type="number" min="0" max="100" step="0.01" value="${v.advance}" required><small>Rak ersättning använder alltid 0 %.</small></label><label>Giltig från<input name="from" type="date" min="2026-01-01" max="2026-12-31" value="${v.from}" ${mode==='edit'||mode==='new'?'readonly':''} required></label><label>Giltig till<input name="to" type="date" value="${v.to}" readonly></label><label class="full">Status<select name="status"><option${selected(v.status,'Förslag')}>Förslag</option><option${selected(v.status,'Under granskning')}>Under granskning</option><option${selected(v.status,'Granskad i demo')}>Granskad i demo</option></select></label></div><p class="muted">${mode==='add'?'Startdatum måste ligga inom den sista versionens period. Den föregående versionen avslutas dagen innan.':'Giltighetsdatum bevaras. Skapa en ny version för att ändra periodindelningen.'}</p><div id="formerror" role="alert"></div><div class="actions"><button type="button" id="cancel">Avbryt</button><button class="primary" type="submit">Spara förslag</button></div></form>`);$('#cancel').onclick=()=>$('#dialog').close();$('#modelform').onsubmit=e=>{e.preventDefault();const f=e.currentTarget.elements;const n={...v,id:mode==='edit'?v.id:partner+'-'+Date.now(),name:f.name.value.trim(),kind:f.kind.value,basis:f.basis.value,rate:+f.rate.value,advance:f.kind.value==='flat'?0:+f.advance.value,from:f.from.value,to:f.to.value,status:f.status.value};try{if(!n.name)throw Error('Ange ett modellnamn.');let versions=structuredClone(vs());if(mode==='new')versions=[n];else if(mode==='edit')versions[index]=n;else{const last=versions.at(-1);if(n.from<=last.from||n.from>last.to)throw Error('Välj ett startdatum senare än sista versionens start och inom dess period.');n.to=last.to;const day=new Date(n.from+'T00:00:00Z');day.setUTCDate(day.getUTCDate()-1);last.to=day.toISOString().slice(0,10);versions.push(n)}M.validate(versions);if(save(s=>{s.versions[partner]=versions;audit(s,`${n.name}: ${money(n.rate)}, ${n.advance} % förskott, ${n.from}–${n.to}. Låsta underlag bevarade.`)},'Modellförslaget sparades. Låst historik är oförändrad.')){$('#dialog').close();render()}}catch(err){$('#formerror').innerHTML=`<p class="error">${esc(err.message)}</p>`}}}
function detail(month){const r=calc(month);showDialog(`<h2>Beräkning · ${label(month)}</h2><p>${vs()[0].kind==='maturity'?'Förskott = godkända avtal × nivå × förskottsandel. Tillägg = max(0, ackumulerad provision − förskott) minus tidigare tillägg. Varje godkännandemånad och version följs separat.':'Rak ersättning = unika kvalificerade avtals-ID:n × nivån som gäller på kvalificeringsdatumet.'}</p><h3>${money(r.advance)} + ${money(r.extra)} = ${money(r.amount)}</h3>${r.cohorts.length?`<div class="tablewrap"><table><thead><tr><th>Godkänd</th><th>Version</th><th>Antal</th><th>Bindande / aktiva</th><th>Förskott totalt</th><th>Tillägg nu</th><th>Ej avräknat</th></tr></thead><tbody>${r.cohorts.map(g=>`<tr><td>${g.month}</td><td>${esc(g.version)}</td><td>${g.count}</td><td>${g.now}</td><td>${money(g.advanceTotal)}</td><td>${money(g.extra)}</td><td>${money(g.remaining)}</td></tr>`).join('')}</tbody></table></div>`:''}<details><summary>Avtal och händelsedatum</summary><div class="tablewrap"><table><thead><tr><th>Avtals-ID</th><th>Godkänd</th><th>Bindande</th><th>Aktiverad</th></tr></thead><tbody>${data().filter(o=>o.approved<=month+'-31').map(o=>`<tr><td>${o.id}</td><td>${o.approved}</td><td>${o.binding&&o.binding<=month+'-31'?o.binding:'—'}</td><td>${o.active&&o.active<=month+'-31'?o.active:'—'}</td></tr>`).join('')}</tbody></table></div></details><p>Exkl. moms. ${r.duplicate} identiska dubbletter ignorerade.</p>`)}
function buildWorkbook(months){if(!window.StudioAccess?.allowed())throw Error('Åtkomst saknas.');const book=new ExcelJS.Workbook();book.creator='Kraftringen Provisionsstudio';book.created=new Date('2026-11-26T12:00:00Z');const invoice=book.addWorksheet('Fakturaunderlag'),summary=book.addWorksheet('Månadsöversikt'),rules=book.addWorksheet('Modellparametrar'),detail=book.addWorksheet('Avräkning'),orders=book.addWorksheet('Orderunderlag');invoice.addRows([['DEMO – EJ FAKTURA – ENDAST FIKTIVA UPPGIFTER'],['Partner',p().name],['Period',months[0]+' – '+months.at(-1)],['Valuta','SEK, exkl. moms'],['Anmärkning','Inga fakturor skickas. Tidigare fakturering och betalningar stäms av separat.'],[],['Månad','Förskott','Övrig ersättning','Totalt','Status','Underlags-ID']]);summary.addRow(['Månad','Godkända','Kvalificerade','Förskott','Övrig ersättning','Summa','Låst vid']);rules.addRow(['Rapportmånad','Versions-ID','Namn','Från','Till','Modell','Kr/avtal','Förskott %','Grund','Status']);detail.addRow(['Rapportmånad','Godkännandemånad','Version','Antal','Kvalificerade hittills','Förskott totalt','Förskott denna månad','Tidigare tillägg','Tillägg denna månad','Återstående förskott']);orders.addRow(['Rapportmånad','Avtals-ID','Partner-ID','Godkänd','Bindande','Aktiverad']);
months.forEach((m,i)=>{const r=report(m),snap=r.snapshot,models=snap?snap.versions:vs(),input=snap?snap.orders:data().filter(o=>o.approved<=m+'-31');const row=8+i;invoice.addRow([m,r.advance,r.extra,{formula:`B${row}+C${row}`,result:r.amount},r.locked?'Låst demo':'Preliminärt förslag',snap?snap.id:`PRELIM-${partner}-${m}`]);summary.addRow([m,r.approved,r.qualified,r.advance,r.extra,r.amount,snap?snap.lockedAt:'']);models.forEach(v=>rules.addRow([m,v.id,v.name,v.from,v.to,kind(v),v.rate,v.advance,basis(v),v.status]));r.cohorts.forEach(g=>detail.addRow([m,g.month,g.version,g.count,g.now,g.advanceTotal,g.advance,g.previousExtra,g.extra,g.remaining]));r.items.forEach(o=>detail.addRow([m,o.cohort,o.version,1,1,0,0,0,o.amount,0]));input.forEach(o=>orders.addRow([m,o.id,o.partner,o.approved,o.binding&&o.binding<=m+'-31'?o.binding:'',o.active&&o.active<=m+'-31'?o.active:'']));});invoice.addRow(['Summa','','',{formula:`SUM(D8:D${7+months.length})`,result:months.reduce((s,m)=>s+report(m).amount,0)}]);for(const ws of book.worksheets){ws.columns.forEach((c,i)=>c.width=i===0?28:24);ws.eachRow((r,i)=>{r.eachCell(c=>{c.font={name:'Arial',size:11,color:{argb:'FF013C57'}};c.alignment={wrapText:true,vertical:'top'}});if(i===1){r.font={bold:true,color:{argb:'FFFFFFFF'}};r.eachCell(c=>{c.fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF013C57'}};c.font={bold:true,color:{argb:'FFFFFFFF'}}})}r.height=i===1?30:28});ws.views=[{state:'frozen',ySplit:1}]}return book;}
window.buildWorkbook=buildWorkbook;
async function download(months){try{const buffer=await buildWorkbook(months).xlsx.writeBuffer(),blob=new Blob([buffer],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),url=URL.createObjectURL(blob),name=`DEMO-${partner}-${months[0]}${months.length>1?'-'+months.at(-1):''}.xlsx`;const a=document.createElement('a');a.href=url;a.download=name;a.textContent='Hämta filen igen: '+name;$('#downloadlink').replaceChildren(a);a.click();toast('Excel-filen är skapad. En reservlänk finns under tabellen.');setTimeout(()=>URL.revokeObjectURL(url),600000)}catch(e){toast('Exporten misslyckades: '+e.message)}}
function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{view=b.dataset.go;location.hash=view;render()});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editModel('edit',+b.dataset.edit));document.querySelectorAll('[data-newmodel]').forEach(b=>b.onclick=()=>editModel('new'));document.querySelectorAll('[data-addversion]').forEach(b=>b.onclick=()=>editModel('add'));document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(b.dataset.detail));document.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>download([b.dataset.export]));document.querySelectorAll('[data-lock]').forEach(b=>b.onclick=()=>{const m=b.dataset.lock;showDialog(`<h2>Lås ${label(m)} i demo</h2><p>Spara ${money(calc(m).amount)}, modellparametrar och avtalsunderlag som en historisk ögonblicksbild. Senare modelländringar ändrar inte denna månad. Ingen verklig attest eller fakturering sker.</p><div class="actions"><button id="lockcancel">Avbryt</button><button class="primary" id="lockconfirm">Lås demounderlaget</button></div>`);$('#lockcancel').onclick=()=>$('#dialog').close();$('#lockconfirm').onclick=()=>{if(save(s=>{const snap=M.snapshot(p(),vs(),m);snap.lockedAt=new Date().toISOString();s.snapshots[partner+'|'+m]=snap;audit(s,`Låste ${m}: ${money(snap.report.amount)}.`)},'Månaden är låst i denna demo.')){$('#dialog').close();render()}}});if($('#localrate'))$('#localrate').onchange=e=>{const value=+e.target.value;if(e.target.value===''||!Number.isFinite(value)||value<0){toast('Ange ett belopp från 0 kr.');return}if(save(s=>{s.localRates[partner]=value},'Jämförelsebelopp sparat.'))render()};if($('#compareA'))$('#compareA').onchange=e=>{compareA=e.target.value;render()};if($('#compareB'))$('#compareB').onchange=e=>{compareB=e.target.value;render()};if($('#exportsummary'))$('#exportsummary').onclick=()=>download(period());if($('#runtests'))$('#runtests').onclick=()=>{render();toast('Testerna har körts på nytt.')}}
$('#partner').innerHTML=M.partners.map(p=>`<option value="${p.id}"${selected(p.id,partner)}>${p.name} · ${p.type}</option>`).join('');$('#partner').onchange=e=>{partner=e.target.value;compareA='';compareB='';render()};function periodChange(){const f=$('#from').value,t=$('#to').value;if(!M.months.includes(f)||!M.months.includes(t)||f>t){toast('Välj en sammanhängande period inom 2026 där från inte är efter till.');$('#from').value=start;$('#to').value=end;return}start=f;end=t;render()}$('#from').onchange=periodChange;$('#to').onchange=periodChange;$('#reset').onclick=()=>{showDialog('<h2>Återställ demodata?</h2><p>Dina lokala modellförslag, låsningar och ändringslogg ersätts med startdemot. Detta går inte att ångra.</p><div class="actions"><button id="resetcancel">Avbryt</button><button id="resetconfirm" class="primary">Återställ demo</button></div>');$('#resetcancel').onclick=()=>$('#dialog').close();$('#resetconfirm').onclick=()=>{try{const next=M.initial();next.revision=state.revision+1;localStorage.setItem(key,JSON.stringify(next));state=next;loadError='';$('#dialog').close();render();toast('Demodata återställdes.')}catch(e){toast(e.message)}}};window.addEventListener('hashchange',()=>{if(tabs.some(t=>t[0]===location.hash.slice(1))){view=location.hash.slice(1);render()}});if(tabs.some(t=>t[0]===location.hash.slice(1)))view=location.hash.slice(1);render();
